-- Imagens unicas do Wikimedia Commons, selecionadas como CC0/Public Domain; requer internet.
USE yummy;
SET NAMES utf8mb4;

CREATE TEMPORARY TABLE tmp_seed_restaurante (
  email VARCHAR(100) NOT NULL PRIMARY KEY, responsavel VARCHAR(100) NOT NULL,
  telefone VARCHAR(20) NOT NULL, nome_fantasia VARCHAR(100) NOT NULL,
  cnpj VARCHAR(20) NOT NULL, categoria VARCHAR(50) NOT NULL, foto_url VARCHAR(500) NOT NULL
) ENGINE=InnoDB;
CREATE TEMPORARY TABLE tmp_seed_produto (
  categoria VARCHAR(50) NOT NULL, nome VARCHAR(100) NOT NULL,
  descricao VARCHAR(255) NOT NULL, preco DECIMAL(10,2) NOT NULL, foto_url VARCHAR(500) NOT NULL
) ENGINE=InnoDB;



START TRANSACTION;
SET @senha_demo = 'scrypt:32768:8:1$d9cxhqbNPOMAe16n$ad384fee38c921f556570fdc32765220da995cfd9a4951ba2bb71edecdf2fd111402e0ebc48bc7ec65abb6f32377b59bfba484e28927f2955e6abc2a70dca884';

SELECT s.responsavel, s.email, @senha_demo, s.telefone, 'restaurante'
FROM tmp_seed_restaurante s;

                        horario_funcionamento, rua, numero, bairro, cidade, cep,
                        tem_mesa, id_plano, foto_url)
SELECT u.id, s.nome_fantasia, s.cnpj, s.categoria, 4.99,
       'Todos os dias, 11:00-22:00', 'Rua dos Sabores', '100', 'Centro', 'Sao Paulo', '01000-000',
       0, NULL, s.foto_url
FROM tmp_seed_restaurante s
JOIN usuario u ON u.email = s.email AND u.tipo = 'restaurante';

SELECT r.id_usuario, p.nome, p.descricao, p.preco, 1, p.foto_url
FROM tmp_seed_restaurante s
JOIN usuario u ON u.email = s.email AND u.tipo = 'restaurante'
JOIN restaurante r ON r.id_usuario = u.id
JOIN tmp_seed_produto p ON p.categoria = s.categoria;

COMMIT;
DROP TEMPORARY TABLE tmp_seed_produto;
DROP TEMPORARY TABLE tmp_seed_restaurante;

